# # # # # # # # # # # # # # # # # # # # Top 10% learner contribution

# # # # # # # # # # # # # # # # # # # sorted_learners = (
# # # # # # # # # # # # # # # # # # #     enrollment_counts
# # # # # # # # # # # # # # # # # # #     .sort_values(
# # # # # # # # # # # # # # # # # # #         "EnrollmentCount",
# # # # # # # # # # # # # # # # # # #         ascending=False
# # # # # # # # # # # # # # # # # # #     )
# # # # # # # # # # # # # # # # # # #     .reset_index(drop=True)
# # # # # # # # # # # # # # # # # # # )

# # # # # # # # # # # # # # # # # # # top_10_percent_count = max(
# # # # # # # # # # # # # # # # # # #     1,
# # # # # # # # # # # # # # # # # # #     int(len(sorted_learners) * 0.10)
# # # # # # # # # # # # # # # # # # # )

# # # # # # # # # # # # # # # # # # # top_10_enrollments = (
# # # # # # # # # # # # # # # # # # #     sorted_learners
# # # # # # # # # # # # # # # # # # #     .head(top_10_percent_count)
# # # # # # # # # # # # # # # # # # #     ["EnrollmentCount"]
# # # # # # # # # # # # # # # # # # #     .sum()
# # # # # # # # # # # # # # # # # # # )

# # # # # # # # # # # # # # # # # # # concentration_percentage = (
# # # # # # # # # # # # # # # # # # #     top_10_enrollments /
# # # # # # # # # # # # # # # # # # #     total_enrollments
# # # # # # # # # # # # # # # # # # # ) * 100


# # # # # # # # # # # # # # # # # # # print(
# # # # # # # # # # # # # # # # # # #     f"\nTop 10% learners account for "
# # # # # # # # # # # # # # # # # # #     f"{concentration_percentage:.2f}% "
# # # # # # # # # # # # # # # # # # #     f"of all enrollments."
# # # # # # # # # # # # # # # # # # # )


