# # # # # # # # # # # # # # # #     transactions["Amount"] = pd.to_numeric(
# # # # # # # # # # # # # # # #         transactions["Amount"],
# # # # # # # # # # # # # # # #         errors="coerce"
# # # # # # # # # # # # # # # #     )

# # # # # # # # # # # # # # # #     courses["CoursePrice"] = pd.to_numeric(
# # # # # # # # # # # # # # # #         courses["CoursePrice"],
# # # # # # # # # # # # # # # #         errors="coerce"
# # # # # # # # # # # # # # # #     )

# # # # # # # # # # # # # # # #     courses["CourseRating"] = pd.to_numeric(
# # # # # # # # # # # # # # # #         courses["CourseRating"],
# # # # # # # # # # # # # # # #         errors="coerce"
# # # # # # # # # # # # # # # #     )

# # # # # # # # # # # # # # # #     # -------------------------
# # # # # # # # # # # # # # # #     # Age Group
# # # # # # # # # # # # # # # #     # -------------------------

# # # # # # # # # # # # # # # #     def create_age_group(age):

# # # # # # # # # # # # # # # #         if pd.isna(age):
# # # # # # # # # # # # # # # #             return "Unknown"

# # # # # # # # # # # # # # # #         if age < 18:
# # # # # # # # # # # # # # # #             return "<18"

# # # # # # # # # # # # # # # #         elif age <= 25:
# # # # # # # # # # # # # # # #             return "18-25"

# # # # # # # # # # # # # # # #         elif age <= 35:
# # # # # # # # # # # # # # # #             return "26-35"

# # # # # # # # # # # # # # # #         elif age <= 45:
# # # # # # # # # # # # # # # #             return "36-45"

# # # # # # # # # # # # # # # #         else:
# # # # # # # # # # # # # # # #             return "45+"

# # # # # # # # # # # # # # # #     users["AgeGroup"] = users["Age"].apply(create_age_group)

