print("\n" + "=" * 80)
print("STEP 28 - RESEARCH PAPER DATA & TABLES PREPARATION")
print("=" * 80)

# ------------------------------------------------------------
# PATHS
# ------------------------------------------------------------

MASTER_PATH = "outputs/reports/edupro_master_dataset.csv"

OUTPUT_DIR = "outputs/reports"

os.makedirs(OUTPUT_DIR, exist_ok=True)

# ------------------------------------------------------------
# LOAD MASTER DATASET
# ------------------------------------------------------------

if not os.path.exists(MASTER_PATH):

    raise FileNotFoundError(
        f"Master dataset not found: {MASTER_PATH}"
    )

df = pd.read_csv(MASTER_PATH)

print(
    f"\nMaster dataset loaded: {df.shape}"
)

# ------------------------------------------------------------
# REQUIRED COLUMNS
# ------------------------------------------------------------

required_columns = [
    "UserID",
    "Age",
    "Gender",
    "CourseID",
    "CourseName",
    "CourseCategory",
    "CourseLevel",
    "CourseType",
    "TransactionDate",
    "Amount"
]

missing_columns = [
    col
    for col in required_columns
    if col not in df.columns
]

if missing_columns:

    raise ValueError(
        f"Missing columns: {missing_columns}"
    )

# ------------------------------------------------------------
# CLEAN DATA
# ------------------------------------------------------------

df["Age"] = pd.to_numeric(
    df["Age"],
    errors="coerce"
)

df["Amount"] = pd.to_numeric(
    df["Amount"],
    errors="coerce"
)

df["TransactionDate"] = pd.to_datetime(
    df["TransactionDate"],
    errors="coerce"
)

for col in [
    "Gender",
    "CourseName",
    "CourseCategory",
    "CourseLevel",
    "CourseType"
]:

    df[col] = (
        df[col]
        .astype(str)
        .str.strip()
    )

# ============================================================
# AGE GROUP
# ============================================================

def create_age_group(age):

    if pd.isna(age):
        return "Unknown"

    if age < 18:
        return "<18"

    elif age <= 25:
        return "18-25"

    elif age <= 35:
        return "26-35"

    elif age <= 45:
        return "36-45"

    else:
        return "45+"


df["AgeGroup"] = df["Age"].apply(
    create_age_group
)

age_order = [
    "<18",
    "18-25",
    "26-35",
    "36-45",
    "45+"
]

# ============================================================
# HELPER FUNCTION
# ============================================================

def save_table(df_table, filename):

    path = os.path.join(
        OUTPUT_DIR,
        filename
    )

    df_table.to_csv(
        path,
        index=False
    )

    print(
        f"✓ {filename}"
    )


# ============================================================
# TABLE 1
# DATASET PROFILE
# ============================================================

dataset_profile = pd.DataFrame({

    "Metric": [

        "Total Enrollment Transactions",

        "Unique Learners",

        "Unique Courses",

        "Course Categories",

        "Course Levels",

        "Course Types",

        "Gender Groups",

        "Minimum Learner Age",

        "Maximum Learner Age",

        "Average Learner Age",

        "Median Learner Age",

        "Average Transaction Amount"
    ],

    "Value": [

        len(df),

        df["UserID"].nunique(),

        df["CourseID"].nunique(),

        df["CourseCategory"].nunique(),

        df["CourseLevel"].nunique(),

        df["CourseType"].nunique(),

        df["Gender"].nunique(),

        df["Age"].min(),

        df["Age"].max(),

        df["Age"].mean(),

        df["Age"].median(),

        df["Amount"].mean()
    ]
})

save_table(
    dataset_profile,
    "step28_table01_dataset_profile.csv"
)

# ============================================================
# TABLE 2
# DEMOGRAPHIC PROFILE
# ============================================================

age_demographic = (
    df.groupby("AgeGroup")
    .agg(
        Learners=("UserID", "nunique"),
        Enrollments=("UserID", "count")
    )
    .reindex(age_order)
    .reset_index()
)

age_demographic[
    "EnrollmentSharePercent"
] = (
    age_demographic["Enrollments"]
    / len(df)
    * 100
)

save_table(
    age_demographic,
    "step28_table02_age_demographic.csv"
)

# ============================================================
# TABLE 3
# GENDER PROFILE
# ============================================================

gender_profile = (
    df.groupby("Gender")
    .agg(
        Learners=("UserID", "nunique"),
        Enrollments=("UserID", "count")
    )
    .reset_index()
)

gender_profile[
    "EnrollmentSharePercent"
] = (
    gender_profile["Enrollments"]
    / len(df)
    * 100
)

gender_profile[
    "AverageEnrollmentsPerLearner"
] = (
    gender_profile["Enrollments"]
    / gender_profile["Learners"]
)

save_table(
    gender_profile,
    "step28_table03_gender_profile.csv"
)

