# ============================================================
# TABLE 11
# LEARNER ENGAGEMENT
# ============================================================

learner_summary = (
    df.groupby("UserID")
    .agg(
        TotalEnrollments=("CourseID", "count"),
        UniqueCourses=("CourseID", "nunique"),
        UniqueCategories=("CourseCategory", "nunique"),
        UniqueLevels=("CourseLevel", "nunique"),
        TotalSpend=("Amount", "sum"),
        AverageTransactionAmount=("Amount", "mean"),
        Age=("Age", "first"),
        Gender=("Gender", "first")
    )
    .reset_index()
)

learner_summary[
    "AgeGroup"
] = learner_summary[
    "Age"
].apply(create_age_group)


def activity_segment(value):

    if value <= 2:
        return "Low Activity"

    elif value <= 5:
        return "Moderate Activity"

    elif value <= 10:
        return "High Activity"

    else:
        return "Very High Activity"


learner_summary[
    "ActivitySegment"
] = learner_summary[
    "TotalEnrollments"
].apply(activity_segment)

activity_table = (
    learner_summary
    .groupby("ActivitySegment")
    .agg(
        Learners=("UserID", "count"),
        TotalEnrollments=("TotalEnrollments", "sum"),
        AverageEnrollments=("TotalEnrollments", "mean"),
        AverageUniqueCourses=("UniqueCourses", "mean")
    )
    .reset_index()
)

activity_table[
    "LearnerSharePercent"
] = (
    activity_table["Learners"]
    / len(learner_summary)
    * 100
)

activity_table[
    "EnrollmentSharePercent"
] = (
    activity_table["TotalEnrollments"]
    / activity_table["TotalEnrollments"].sum()
    * 100
)

save_table(
    activity_table,
    "step28_table11_learner_engagement.csv"
)

# ============================================================
# TABLE 12
# TOP COURSES
# ============================================================

top_courses = (
    df.groupby(
        [
            "CourseID",
            "CourseName",
            "CourseCategory",
            "CourseLevel"
        ]
    )
    .agg(
        Enrollments=("UserID", "count"),
        UniqueLearners=("UserID", "nunique"),
        AverageTransactionAmount=("Amount", "mean")
    )
    .reset_index()
    .sort_values(
        "Enrollments",
        ascending=False
    )
    .head(10)
)

top_courses[
    "EnrollmentSharePercent"
] = (
    top_courses["Enrollments"]
    / len(df)
    * 100
)

top_courses[
    "Rank"
] = range(
    1,
    len(top_courses) + 1
)

save_table(
    top_courses,
    "step28_table12_top10_courses.csv"
)

# ============================================================
# TABLE 13
# MONTHLY ENROLLMENT
# ============================================================

monthly = (
    df.dropna(
        subset=["TransactionDate"]
    )
    .assign(
        Year=lambda x:
        x["TransactionDate"].dt.year,

        Month=lambda x:
        x["TransactionDate"].dt.month,

        MonthName=lambda x:
        x["TransactionDate"].dt.strftime("%B")
    )
    .groupby(
        [
            "Year",
            "Month",
            "MonthName"
        ]
    )
    .size()
    .reset_index(
        name="Enrollments"
    )
    .sort_values(
        [
            "Year",
            "Month"
        ]
    )
)

monthly[
    "MoMChangePercent"
] = (
    monthly["Enrollments"]
    .pct_change()
    * 100
)

save_table(
    monthly,
    "step28_table13_monthly_enrollment.csv"
)

# ============================================================
# TABLE 14
# BEGINNER VS ADVANCED
# ============================================================

level_normalized = (
    df["CourseLevel"]
    .astype(str)
    .str.strip()
    .str.lower()
)

beginner_count = int(
    level_normalized
    .str.contains(
        "beginner",
        na=False
    )
    .sum()
)

advanced_count = int(
    level_normalized
    .str.contains(
        "advanced",
        na=False
    )
    .sum()
)

comparison_total = (
    beginner_count
    + advanced_count
)

if comparison_total > 0:

    beginner_share = (
        beginner_count
        / comparison_total
        * 100
    )

    advanced_share = (
        advanced_count
        / comparison_total
        * 100
    )

else:

    beginner_share = 0
    advanced_share = 0

beginner_advanced_table = pd.DataFrame({

    "CourseLevel": [
        "Beginner",
        "Advanced"
    ],

    "Enrollments": [
        beginner_count,
        advanced_count
    ],

    "SharePercent": [
        beginner_share,
        advanced_share
    ]
})

save_table(
    beginner_advanced_table,
    "step28_table14_beginner_advanced.csv"
)

# ============================================================
# TABLE 15
# COURSE PERFORMANCE
# ============================================================

course_performance = (
    df.groupby(
        [
            "CourseID",
            "CourseName",
            "CourseCategory",
            "CourseLevel"
        ]
    )
    .agg(
        Enrollments=("UserID", "count"),
        UniqueLearners=("UserID", "nunique"),
        AverageTransactionAmount=("Amount", "mean")
    )
    .reset_index()
    .sort_values(
        "Enrollments",
        ascending=False
    )
)

course_performance[
    "EnrollmentSharePercent"
] = (
    course_performance["Enrollments"]
    / len(df)
    * 100
)

save_table(
    course_performance,
    "step28_table15_course_performance.csv"
)

# ============================================================
# TABLE 16
# LEARNER COURSE DIVERSITY
# ============================================================

learner_diversity = (
    learner_summary
    .groupby("UniqueCourses")
    .size()
    .reset_index(
        name="NumberOfLearners"
    )
    .sort_values(
        "UniqueCourses"
    )
)

learner_diversity[
    "LearnerSharePercent"
] = (
    learner_diversity["NumberOfLearners"]
    / learner_diversity["NumberOfLearners"].sum()
    * 100
)

save_table(
    learner_diversity,
    "step28_table16_learner_course_diversity.csv"
)

# ============================================================
# TABLE 17
# COURSE CONCENTRATION
# ============================================================

course_sorted = course_performance.sort_values(
    "Enrollments",
    ascending=False
)

course_concentration = []

for n in [1, 3, 5, 10]:

    if len(course_sorted) >= n:

        enrollment_count = (
            course_sorted
            .head(n)["Enrollments"]
            .sum()
        )

        share = (
            enrollment_count
            / len(df)
            * 100
        )

        course_concentration.append({

            "TopCourses": n,

            "EnrollmentCount":
            enrollment_count,

            "EnrollmentSharePercent":
            share
        })

course_concentration = pd.DataFrame(
    course_concentration
)

save_table(
    course_concentration,
    "step28_table17_course_concentration.csv"
)

# ============================================================
# TABLE 18
# LEARNER CONCENTRATION
# ============================================================

learner_sorted = learner_summary.sort_values(
    "TotalEnrollments",
    ascending=False
)

learner_concentration = []

for percentage in [
    1,
    5,
    10,
    20
]:

    number_learners = max(
        1,
        int(
            np.ceil(
                len(learner_sorted)
                * percentage
                / 100
            )
        )
    )

    enrollments = (
        learner_sorted
        .head(number_learners)
        ["TotalEnrollments"]
        .sum()
    )

    share = (
        enrollments
        / len(df)
        * 100
    )

    learner_concentration.append({

        "TopLearnerPercent":
        percentage,

        "NumberOfLearners":
        number_learners,

        "Enrollments":
        enrollments,

        "EnrollmentSharePercent":
        share
    })

learner_concentration = pd.DataFrame(
    learner_concentration
)

save_table(
    learner_concentration,
    "step28_table18_learner_concentration.csv"
)

