# ============================================================
# TABLE 20
# KEY RESEARCH FINDINGS
# ============================================================

key_findings = []

# Age
age_valid = age_demographic[
    age_demographic["Enrollments"] > 0
]

if not age_valid.empty:

    row = age_valid.loc[
        age_valid["Enrollments"].idxmax()
    ]

    key_findings.append({

        "FindingID": 1,

        "ResearchArea":
        "Age Group",

        "Finding":
        f"{row['AgeGroup']} is the most active "
        f"age group by enrollment.",

        "Evidence":
        f"{int(row['Enrollments']):,} enrollments "
        f"({row['EnrollmentSharePercent']:.2f}%)."
    })

# Gender
if not gender_profile.empty:

    row = gender_profile.loc[
        gender_profile["Enrollments"].idxmax()
    ]

    key_findings.append({

        "FindingID": 2,

        "ResearchArea":
        "Gender",

        "Finding":
        f"{row['Gender']} has the highest "
        f"observed enrollment volume.",

        "Evidence":
        f"{row['EnrollmentSharePercent']:.2f}% "
        f"of enrollments."
    })

# Category
if not category_table.empty:

    row = category_table.iloc[0]

    key_findings.append({

        "FindingID": 3,

        "ResearchArea":
        "Course Category",

        "Finding":
        f"{row['CourseCategory']} is the most "
        f"preferred course category.",

        "Evidence":
        f"{int(row['Enrollments']):,} enrollments "
        f"({row['EnrollmentSharePercent']:.2f}%)."
    })

# Level
if not level_table.empty:

    row = level_table.iloc[0]

    key_findings.append({

        "FindingID": 4,

        "ResearchArea":
        "Course Level",

        "Finding":
        f"{row['CourseLevel']} is the most "
        f"preferred course level.",

        "Evidence":
        f"{int(row['Enrollments']):,} enrollments "
        f"({row['EnrollmentSharePercent']:.2f}%)."
    })

# Top course
if not top_courses.empty:

    row = top_courses.iloc[0]

    key_findings.append({

        "FindingID": 5,

        "ResearchArea":
        "Course Popularity",

        "Finding":
        f"{row['CourseName']} is the most "
        f"enrolled course.",

        "Evidence":
        f"{int(row['Enrollments']):,} enrollments."
    })

# Activity
if not activity_table.empty:

    row = activity_table.loc[
        activity_table[
            "TotalEnrollments"
        ].idxmax()
    ]

    key_findings.append({

        "FindingID": 6,

        "ResearchArea":
        "Learner Engagement",

        "Finding":
        f"{row['ActivitySegment']} learners "
        f"contribute the largest enrollment volume.",

        "Evidence":
        f"{row['EnrollmentSharePercent']:.2f}% "
        f"of enrollments."
    })

# Peak month
if not monthly.empty:

    row = monthly.loc[
        monthly["Enrollments"].idxmax()
    ]

    key_findings.append({

        "FindingID": 7,

        "ResearchArea":
        "Temporal Behavior",

        "Finding":
        f"{row['MonthName']} {int(row['Year'])} "
        f"has the highest enrollment activity.",

        "Evidence":
        f"{int(row['Enrollments']):,} enrollments."
    })

key_findings = pd.DataFrame(
    key_findings
)

save_table(
    key_findings,
    "step28_table20_key_research_findings.csv"
)

