# CREATE RESEARCH PAPER RESULTS TEXT
# ============================================================

results_text = []

results_text.append(
    "RESEARCH PAPER - RESULTS SUMMARY"
)

results_text.append(
    "=" * 80
)

results_text.append("")

results_text.append(
    "1. DATASET PROFILE"
)

results_text.append(
    f"The analysis examined {len(df):,} enrollment "
    f"transactions involving {df['UserID'].nunique():,} "
    f"unique learners and {df['CourseID'].nunique():,} "
    f"unique courses."
)

results_text.append("")

if not age_valid.empty:

    row = age_valid.loc[
        age_valid["Enrollments"].idxmax()
    ]

    results_text.append(
        "2. AGE GROUP ANALYSIS"
    )

    results_text.append(
        f"The {row['AgeGroup']} age group recorded "
        f"the highest enrollment volume with "
        f"{int(row['Enrollments']):,} enrollments."
    )

results_text.append("")

if not gender_profile.empty:

    row = gender_profile.loc[
        gender_profile["Enrollments"].idxmax()
    ]

    results_text.append(
        "3. GENDER ANALYSIS"
    )

    results_text.append(
        f"The {row['Gender']} group recorded "
        f"the highest observed enrollment share "
        f"at {row['EnrollmentSharePercent']:.2f}%."
    )

results_text.append("")

if not category_table.empty:

    row = category_table.iloc[0]

    results_text.append(
        "4. COURSE CATEGORY ANALYSIS"
    )

    results_text.append(
        f"{row['CourseCategory']} was the most "
        f"preferred course category, accounting for "
        f"{row['EnrollmentSharePercent']:.2f}% "
        f"of enrollments."
    )

results_text.append("")

if not level_table.empty:

    row = level_table.iloc[0]

    results_text.append(
        "5. COURSE LEVEL ANALYSIS"
    )

    results_text.append(
        f"{row['CourseLevel']} was the most "
        f"preferred course level with "
        f"{row['EnrollmentSharePercent']:.2f}% "
        f"of enrollments."
    )

results_text.append("")

if not top_courses.empty:

    row = top_courses.iloc[0]

    results_text.append(
        "6. COURSE POPULARITY"
    )

    results_text.append(
        f"{row['CourseName']} recorded the highest "
        f"number of enrollments."
    )

results_text.append("")

if not monthly.empty:

    row = monthly.loc[
        monthly["Enrollments"].idxmax()
    ]

    results_text.append(
        "7. TEMPORAL ANALYSIS"
    )

    results_text.append(
        f"The highest monthly enrollment activity "
        f"occurred in {row['MonthName']} "
        f"{int(row['Year'])}, with "
        f"{int(row['Enrollments']):,} enrollments."
    )

results_text.append("")

results_text.append(
    "8. SDG 4 CONNECTION"
)

results_text.append(
    "The study provides descriptive evidence relevant "
    "to SDG 4 themes including access to education, "
    "skills development and equitable participation."
)

results_text.append("")

results_text.append(
    "9. INTERPRETATION"
)

results_text.append(
    "The results indicate that learner enrollment "
    "behavior varies across demographic groups, "
    "course categories, course levels and time periods. "
    "Cross-dimensional analysis provides a more detailed "
    "understanding of learner preferences than examining "
    "individual variables separately."
)

